      if (!(isFinite(pFar) && pFar > 0)) fail('L7分级/非有限', '轨道每格 ' + pFar + 'px（须为有限正数）');
      if (pNear <= 3.0) fail('L7分级/贴地不可见', '每格仅 ' + pNear.toFixed(2) + 'px（应 > 3）');
      if (pFar >= 0.9) fail('L7分级/高空未隐藏', '每格 ' + pFar.toFixed(2) + 'px（应 < 0.9）');
