    st.ms = +(st.acc / Math.max(1, st.frames)).toFixed(1);
    st.p95 = +sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95))].toFixed(1);
    st.fps = +(1000 / Math.max(0.1, st.ms)).toFixed(0);
    st.frames = 0; st.acc = 0;
