    var pt = M._ptr;
    if (!pt || pt.out) return false;
    var w = pt.w, h = pt.h;
    if (!(w > 8) || !(h > 8)) return false;
    var band = Math.max(10, Math.round(Math.min(w, h) * M.EDGE_PAN_BAND));
    var dx = (pt.x > w - band) ? 1 : ((pt.x < band) ? -1 : 0);
    var dy = (pt.y > h - band) ? 1 : ((pt.y < band) ? -1 : 0);
