      var _k = 1 - Math.exp(-_dt / _tau);
      M._surfCamAnchor.lerp(P, Math.min(1, _k));
      /* 贴回球壳：两帧之间走的是**弦**，不修正会一路往地里沉。
         只修长度、不动方向 —— 角度上的滞后（= 观感里的"人往前挪"）完整保留。 */
      var _aL = M._surfCamAnchor.length() || 1;
