    if (rp.autoBattles) mil.push('<div class="op-hint">⚔️ ' + rp.autoBattles
      + ' 场战斗已自动打完（全程回见「公文 → 战报」）</div>');
    if (rp.marchMsg) mil.push('<div class="op-hint">🚩 ' + U.escape(rp.marchMsg) + '</div>');
    if (mil.length) h += ui.sealH('军务') + mil.join('');

