  ui.ATTACH_CN186 = { tong: '指挥', nz: '治理', yw: '武力', zm: '谋略', spd: '速度', atk: '攻击', def: '防御', sta: '体力' };
  /* v89.187（老板 1）：品质徽标（低/中/高 · 颜色同表）——挂件行/选择窗/合成区共读 */
