    html += '<div class="exp-sec exp-a-troops"><div class="exp-sec-t">派遣兵力（<span id="exp-cap-t">' +
      U.escape(ui.expCapLabelOf(c, t, ui._expMode)) + '</span>）</div>';
    html += '<div class="exp-troops exp-body" data-mode="' + cur.id + '">' + troopBlock + '</div>';
